const crypto = require('crypto');
const secret = $env.VIKUNJA_WEBHOOK_SECRET;
const item = $input.first();
const signature = String(item.json.headers['x-vikunja-signature'] || '');
const rawBody = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
const a = Buffer.from(signature);
const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Invalid Vikunja webhook signature');
}
return [{ json: item.json.body }];

const content = $input.first().json.choices[0].message.content;
const start = content.indexOf('{');
const end = content.lastIndexOf('}');
if (start === -1 || end <= start) throw new Error('Omniroute reply contained no JSON object');
const triage = JSON.parse(content.slice(start, end + 1));
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const list = (v) => (Array.isArray(v) ? v : []).map(esc);
const subtasks = list(triage.subtasks);
const labels = list(triage.labels);
const comment = '<p><strong>AI Triage</strong></p>' +
  '<p>Suggested subtasks:</p><ul>' + subtasks.map((s) => '<li>' + s + '</li>').join('') + '</ul>' +
  '<p>Suggested priority: ' + esc(triage.priority) + '<br>Suggested labels: ' + labels.join(', ') + '<br>Effort estimate: ' + esc(triage.effort_estimate) + '</p>';
return [{ json: { comment, taskId: $('Verify Signature').first().json.data.task.id } }];
